// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(uint64 number, uint64 timestamp, uint256 basefee, bytes32 hash, uint64 seq, bytes32 batcher, uint256 overhead, uint256 scalar) public {
        // depositorAccount defaults to address(0); prank as it so the require passes in both versions
        vm.prank(address(0));
        c.setL1BlockValues(number, timestamp, basefee, hash, seq, batcher, overhead, scalar);
        // Reference never mutates state: number stays 0 for every input
        assertTrue(c.number() == 0);
    }
}
